def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate solid separator rows and columns.
    sep_rows = [r for r in range(h)
                if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(length, separators):
        result = []
        start = 0
        for x in separators:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < length:
            result.append((start, length))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    # The non-2x2 object is the pattern to replicate.
    pattern = None
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            coords = [(r-r0, c-c0)
                      for r in range(r0, r1)
                      for c in range(c0, c1)
                      if grid[r][c] != 0]
            if not coords:
                continue
            rows = [r for r, c in coords]
            cols = [c for r, c in coords]
            is_marker = (len(coords) == 4 and max(rows)-min(rows) == 1
                         and max(cols)-min(cols) == 1)
            if not is_marker and (pattern is None or len(coords) > len(pattern)):
                pattern = coords

    if pattern is None:
        return [row[:] for row in grid]

    # Each band's color is given by its 2x2 marker in the leftmost compartment.
    colors = []
    for r0, r1 in row_spans:
        counts = {}
        c0, c1 = col_spans[0]
        for r in range(r0, r1):
            for c in range(c0, c1):
                v = grid[r][c]
                if v:
                    counts[v] = counts.get(v, 0) + 1
        colors.append(max(counts, key=counts.get) if counts else None)

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(row_spans):
        color = colors[i]
        for c0, c1 in col_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            if color is not None:
                for dr, dc in pattern:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = color
    return out
